html:
{%- set data = ti_export(doc) -%}
<!doctype html>
<html><head><meta charset="utf-8">
<style>{{ ti_print_css() }}</style>
<style>
{% if data.orientation == "landscape" %}.print-format { page-width: 279.4mm; page-height: 215.9mm; orientation: Landscape; page: landscape; }{% endif %}
.print-format .ti-print .ti-table { font-size: {{ data.font_pt }}pt; }
.print-format .ti-print .ti-table .ti-head-row th { font-size: {{ data.head_font_pt }}pt; }
</style>
</head><body><div class="ti-print">
<table class="ti-table ti-list ti-fixed ti-count">
<colgroup><col style="width: {{ data.seq_width_pt }}pt">{% for column in data.columns %}<col{% if column.width_pt %} style="width: {{ column.width_pt }}pt"{% endif %}>{% endfor %}{% for width in data.extra_widths_pt %}<col style="width: {{ width }}pt">{% endfor %}</colgroup>
<thead>
<tr class="ti-title-row"><th colspan="{{ data.columns|length + 3 }}"><span class="ti-title">{% if "盘点" in data.title %}{{ data.title|e }}{% else %}{{ (data.title ~ " 盘点表")|e }}{% endif %}</span></th></tr>
<tr class="ti-filter-row"><th colspan="{{ data.columns|length + 3 }}" class="ti-filters">{{ data.row_count|e }} 行 · {{ data.generated_at|e }}{% if data.filters %} · {{ data.filters|join("；")|e }}{% endif %}</th></tr>
<tr class="ti-head-row"><th class="ti-seq">#</th>{% for column in data.columns %}<th class="{% if column.is_main %}ti-main{% elif column.wrap %}ti-wrap{% else %}ti-nowrap{% endif %}">{{ column.label|e }}</th>{% endfor %}<th class="ti-write">实盘</th><th class="ti-write">备注</th></tr>
</thead>
<tbody>
{%- for row in data.rows %}
{%- if row.style.startswith("group-") %}
<tr class="ti-group"><th colspan="{{ data.columns|length + 3 }}">{{ row["values"][0]|e }}</th></tr>
{%- else %}
<tr{% if row.style == "total" %} class="ti-total"{% endif %}><td class="ti-seq">{% if row.style == "row" %}{{ row.sequence }}{% endif %}</td>{% for value in row["values"] %}<td class="{% set column = data.columns[loop.index0] %}{% if column.is_main %}ti-main{% elif column.wrap %}ti-wrap{% else %}ti-nowrap{% endif %}{% if column.align == "number" %} ti-num{% elif column.align == "center" %} ti-center{% endif %}">{{ value|e }}</td>{% endfor %}<td class="ti-write"></td><td class="ti-write"></td></tr>
{%- endif %}
{%- endfor %}
</tbody>
</table>
<div class="ti-signatures"><span>盘点人：________________</span><span>复核人：________________</span><span>日期：________________</span></div>
</div></body></html>
